// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {

        bytes memory sig = abi.encodeWithSelector(bytes4(keccak256("getPrice(bytes32,uint256,bytes)")), identifier, time, ancillaryData);
        (bool success, bytes memory ret) = address(c).staticcall(sig);

        int256 returned = 0;
        if (success && ret.length >= 32) {
            returned = abi.decode(ret, (int256));
        }

        assertTrue(returned == 0);
    }
}
